head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 1

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.gAcptNo;
scwin.vScrenID = 'ULDSTF25300.gfm';
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {

};

// 공시일자, 팀, 담당자 세팅
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅(공시일자)
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_EDATE.setValue(vCurDate); // 현재날짜	

};


//조회 버튼
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=DISCLS_EXTRC_INFO_MONITOR_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.dsclstat.select.meta.formextr.monitor" + "&{P}param01=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&{P}param02=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&{P}param03=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param05=" + $c.stf.getObjectValue(edt_SDATE) + "&{P}param06=" + $c.stf.getObjectValue(edt_EDATE) + "&{P}param07=" + $c.stf.getObjectValue(txb_FORM_CD) + "&{P}param08=" + $c.stf.getObjectValue(txb_FORM_CD) + "&{P}param09=" + $c.stf.getObjectValue(rdo_Extr_Yn) + "&{P}param10=" + $c.stf.getObjectValue(rdo_Extr_Yn) + "&{P}param11=" + $c.stf.getObjectValue(rdo_Extr_Yn) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Grid.Reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(eval(obj), "ACPT_NO");
};
scwin.fn_OpenDisclViewer_K = async function(pAcptNo, pViewerStat) {
    var vHttp;
    if (js_svrGubun.indexOf("test") > -1) {
        vHttp = g_test_stf_url;
    } else if (js_svrGubun == "dev" || js_svrGubun == 'local') {
        vHttp = g_dev_stf_url;
    } else {
        vHttp = g_real_stf_url;
    }
    var url = vHttp + "/dsclproc/ULDSTF10001.gfm?" + "gAcptNo=" + pAcptNo + "&gViewerStat=" + pViewerStat + "&frameID=" + frame.FrameID + "&gAccssAuthTpCd=01" + "&screnID=" + scwin.vScrenID;
    var winTitle = "공시뷰어";
    if ($c.frame.path("/top") != undefined) {

	//----W-Craft WebSquare 변환 확인: WinOpen_child----//
        $c.frame.path("/top").WinOpen_child("viewer" + pAcptNo, url, winTitle, 1000, 800);
    } else {
        await $c.frame.CreateFrame("viewer" + pAcptNo, url, winTitle, 10, 10, 1000, 800, "window", 0, 0, true);
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업

};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE); //기간선택 콤보박스

};
scwin.btn_EDATE_onclick = function() {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_EDATE); //공시일자-시작일 이미지 버튼 클릭 시 달력 팝업

};
scwin.btn_SDATE_onclick = function() {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_SDATE); //공시일자-종료일 이미지 버튼 클릭 시 달력 팝업

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "ACPT_NO") {
        scwin.fn_OpenDisclViewer_K(scwin.gAcptNo, "R"); //(정정)공시일 컬럼 더블클릭시 관련 보고서 뷰잉

    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search(); //조회 버튼

};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page); //총 건수

};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "메타추출모니터링", "", "2"); //엑셀 다운로드

};
scwin.gform_onload = function() {
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM); //법인코드 및 법인명(회사명) 관련
    Grd_com_isur.style.zIndex = 30;
    $c.libRoundPanel.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용

    scwin.fn_SetCode(); //공시일자(from~to)
    scwin.fn_Init(); //시장구분

    scwin.fn_Search();
};
